package com.hbm.machine.exposurechamber;
import com.google.gson.*;
import com.hbm.config.GeneralModes;
import com.hbm.recipe.generic.*;
import com.mojang.logging.LogUtils;
import java.nio.file.*;
import java.util.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.crafting.*;
import net.neoforged.bus.api.EventPriority;
import net.neoforged.fml.loading.FMLPaths;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.event.OnDatapackSyncEvent;
import net.neoforged.neoforge.event.server.ServerAboutToStartEvent;
/** Source SerializableRecipe particle/ingredient/output grammar and first-match order, not a second processing engine. */
public final class ExposureChamberRecipes {
 private static final Map<RecipeManager,Map<ResourceLocation,RecipeHolder<?>>> INSTALLED=new WeakHashMap<>();private static final Map<String,String> ALIASES=new LinkedHashMap<>();private static final List<String> UNRESOLVED=new ArrayList<>();
 public static void register(){try(var stream=ExposureChamberRecipes.class.getResourceAsStream("/hbm/machine-exposure-chamber92-item-aliases.json")){if(stream==null)throw new IllegalStateException("Missing source chamber aliases");JsonParser.parseReader(new java.io.InputStreamReader(stream,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject().entrySet().forEach(e->ALIASES.put(e.getKey(),e.getValue().getAsString()));}catch(java.io.IOException error){throw new IllegalStateException(error);}NeoForge.EVENT_BUS.addListener((ServerAboutToStartEvent e)->install(e.getServer()));NeoForge.EVENT_BUS.addListener(EventPriority.LOWEST,(OnDatapackSyncEvent e)->{var server=e.getPlayerList().getServer();if(e.getPlayer()==null||!INSTALLED.containsKey(server.getRecipeManager()))install(server);});}
 public static List<ExposureChamberRecipe> recipes(RecipeManager manager){return manager.getAllRecipesFor(ExposureChamberContent.TYPE.get()).stream().map(RecipeHolder::value).sorted(Comparator.comparingInt(r->r.data().order())).toList();}public static List<String> unresolved(){return List.copyOf(UNRESOLVED);}
    public static void reload(MinecraftServer server) { install(server); }
 private static void install(MinecraftServer server){var manager=server.getRecipeManager();var previous=INSTALLED.getOrDefault(manager,Map.of());var merged=new LinkedHashMap<ResourceLocation,RecipeHolder<?>>();for(var holder:manager.getOrderedRecipes())if(previous.get(holder.id())!=holder)merged.put(holder.id(),holder);var additions=new LinkedHashMap<ResourceLocation,RecipeHolder<?>>();UNRESOLVED.clear();Path dir=FMLPaths.CONFIGDIR.get().resolve("hbmRecipes"),active=dir.resolve("hbmExposureChamber.json");try{Files.createDirectories(dir);boolean custom=Files.isRegularFile(active);JsonObject root;if(custom){merged.values().removeIf(h->h.value().getType()==ExposureChamberContent.TYPE.get());try(var reader=Files.newBufferedReader(active)){root=JsonParser.parseReader(reader).getAsJsonObject();}}else try(var stream=ExposureChamberRecipes.class.getResourceAsStream("/hbm/machine-exposure-chamber92-source-recipes.json")){if(stream==null)throw new IllegalStateException("Missing source chamber recipes");root=JsonParser.parseReader(new java.io.InputStreamReader(stream,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();}var template=new JsonObject();var exported=new JsonArray();template.add("recipes",exported);int order=0;for(var value:root.getAsJsonArray("recipes")){var row=value.getAsJsonObject();if(!custom&&row.has("sourceMode")&&row.get("sourceMode").getAsString().equals("expensive")!=GeneralModes.expensive())continue;int index=order++;try{var particle=GenericRecipeConfigCodec.readIngredient(row.getAsJsonArray("particle"),ALIASES,server.registryAccess());var ingredient=GenericRecipeConfigCodec.readIngredient(row.getAsJsonArray("ingredient"),ALIASES,server.registryAccess());var output=GenericRecipeConfigCodec.readStack(row.getAsJsonArray("output"),ALIASES);if(particle.examples().isEmpty()||ingredient.examples().isEmpty()||output.isEmpty())throw new IllegalArgumentException("Actual source input/output is not registered");var data=new GenericRecipeData("exposure_"+index,200,10000,List.of(particle,ingredient),List.of(),List.of(new GenericOutput(output)),List.of(),List.of(),"",output.copy(),false,"",index);var id=ResourceLocation.fromNamespaceAndPath("hbm","exposure_chamber/"+(custom?"config/":"default/")+index);additions.put(id,new RecipeHolder<>(id,new ExposureChamberRecipe(data)));var generic=GenericRecipeConfigCodec.write(data,server.registryAccess());var export=new JsonObject();export.add("particle",generic.getAsJsonArray("inputItem").get(0));export.add("ingredient",generic.getAsJsonArray("inputItem").get(1));export.add("output",GenericRecipeConfigCodec.writeStack(output));exported.add(export);}catch(Exception error){UNRESOLVED.add("row "+index+": "+error.getMessage());}}if(!custom)Files.writeString(dir.resolve("_hbmExposureChamber.json"),new GsonBuilder().setPrettyPrinting().create().toJson(template)+"\n");}catch(Exception error){LogUtils.getLogger().error("Cannot load original exposure chamber recipes",error);}additions.forEach(merged::put);manager.replaceRecipes(merged.values());INSTALLED.put(manager,additions);for(var error:UNRESOLVED)LogUtils.getLogger().warn("Unbound source exposure chamber recipe: {}",error);}
 private ExposureChamberRecipes(){}
}
